              "short_description": [
                  {
                      "language": "en",
                      "text": "Do you remember when Katy Perry killed a nun? This week, we're talking Popes, pop flops, and Paul — Mescal that is. Come get into white boys with gold chains, disloyal snitches in Vatican City, and the one and only Camila Cabello... Because it’s always Camila Cabello. And for W+ subscribers, we're revisiting the best couple on the HBO series Girls: Marnie and Desi.Listen to Lemme Say This on the .."
                  }
              ],
